// ADR 0007 (D131/D197/D211): maker colours come from one table, cockpit/src/livery-table.ts (generated by sync-livery.mjs).
// No other cockpit source or native Swift file may hard-code a maker colour; read it from the table instead.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,readdirSync} from 'node:fs';
import {join,relative} from 'node:path';
import {fileURLToPath} from 'node:url';

const desktop=fileURLToPath(new URL('../../../',import.meta.url));
const src=join(desktop,'cockpit/src'),native=join(desktop,'native');
// The table, its vendored website copy (both written by sync-livery.mjs) and nothing else.
const ALLOWED=new Set(['cockpit/src/livery-table.ts','cockpit/src/livery-shared.json']);
const SKIP_DIRS=new Set(['node_modules','.build','.tmp','.swiftpm','DerivedData']);

/** Every maker colour the table knows: UI accent, collision alternate and website rocket livery. */
export function makerHexes(){
 const text=readFileSync(join(src,'livery-table.ts'),'utf8')+readFileSync(join(src,'livery-shared.json'),'utf8');
 return new Set([...text.matchAll(/#([0-9a-f]{6})\b/gi)].map(m=>m[1].toLowerCase()));
}
/** `#rrggbb` or `0xrrggbb` (any case) naming a maker colour; returns the matched hex values. */
export function offenders(text,hexes){
 return [...text.matchAll(/(?:#|0x)([0-9a-f]{6})(?![0-9a-f])/gi)].map(m=>m[1].toLowerCase()).filter(h=>hexes.has(h));
}
function* walk(dir,keep){
 for(const e of readdirSync(dir,{withFileTypes:true})){
  if(e.isDirectory()){if(!SKIP_DIRS.has(e.name))yield* walk(join(dir,e.name),keep);}
  else if(keep(e.name))yield join(dir,e.name);
 }
}

test('ADR 0007 control: the scanner sees maker colours in CSS, TS and Swift spellings, and ignores other colours',()=>{
 const hexes=makerHexes();
 for(const h of ['10a37f','3859ff','f5e642','f79dcb','d97757','8dabfd','ececec'])assert.ok(hexes.has(h),'table lost '+h);
 assert.deepEqual(offenders("const c='#10A37F';",hexes),['10a37f']);
 assert.deepEqual(offenders('let glm = Color(hex: 0x3859FF)',hexes),['3859ff']);
 assert.deepEqual(offenders('color: #123456; border: #10a37f80;',hexes),[]);
});
test('ADR 0007 no cockpit source or native Swift file hard-codes a maker colour outside livery-table.ts',()=>{
 const hexes=makerHexes(),hits=[];
 const files=[...walk(src,n=>/\.(ts|tsx|js|mjs|css|html|json)$/.test(n)),...walk(native,n=>n.endsWith('.swift'))];
 assert.ok(files.length>50,'scan found too few files');
 for(const f of files){
  const rel=relative(desktop,f);
  if(ALLOWED.has(rel))continue;
  const found=offenders(readFileSync(f,'utf8'),hexes);
  if(found.length)hits.push(rel+': #'+[...new Set(found)].join(', #'));
 }
 assert.deepEqual(hits,[],'take maker colours from cockpit/src/livery-table.ts (brandColour/rocketColour), not literals:\n'+hits.join('\n'));
});
